<script setup lang="ts">
import { useApi, isCancelled } from "./lib/api";
const api = useApi();
import { latestRequest } from "./lib/requests";
const loadRequest = latestRequest();
onUnmounted(()=>loadRequest.cancel());
import { computed, nextTick, onMounted, onUnmounted, reactive, ref, watch } from 'vue';
import { Save, Building2, ShieldCheck, Navigation, Download, Globe2, Search, RefreshCw, TriangleAlert } from 'lucide-vue-next';
import { t, locale } from './i18n';
import type { SiteSettings } from './types';
import { DEFAULT_ADMIN_SIDEBAR, DEFAULT_MEMBER_SIDEBAR, MEMBER_NAVIGATION, type NavigationItem } from './lib/navigation';
import { countryOptions } from './lib/countries';
export type { SiteSettings } from './types';
const props=withDefaults(defineProps<{remoteSite?:boolean;publicFeaturesEnabled?:boolean;section?:string;adminNavigation?:NavigationItem[]}>(),{section:'site',adminNavigation:()=>[]});
const emit=defineEmits<{saved:[]; updatePublicFeaturesEnabled:[value:boolean]; showSection:[value:string]}>();
const form=reactive<SiteSettings>({panel_name:'',organization:'',default_locale:'zh-CN',support_email:'',login_notice:'',registration_enabled:false,registration_captcha:false,revision:'',sidebar_admin:[...DEFAULT_ADMIN_SIDEBAR],sidebar_member:[...DEFAULT_MEMBER_SIDEBAR],client_download_relay:false,country_access_enabled:false,country_access_blocked:[],country_access_reason:''});
const ready=ref(false),busy=ref(false),error=ref(''),saved=ref(false);
const navigationRole=ref<'admin'|'member'>('admin'),countrySearch=ref(''),countryFilter=ref('all'),confirmOwnCountry=ref(false);
type AccessPreview={enabled:boolean;allowed:boolean;ip:string;country_code:string;country_name:string;reason:string;database_version:string};
const accessPreview=ref<AccessPreview|null>(null),accessLoading=ref(false),accessError=ref('');
const navigationOptions=computed(()=>navigationRole.value==='admin'?props.adminNavigation:MEMBER_NAVIGATION);
const navigationSelection=computed({get:()=>navigationRole.value==='admin'?form.sidebar_admin:form.sidebar_member,set:value=>{if(navigationRole.value==='admin')form.sidebar_admin=value;else form.sidebar_member=value;}});
const countries=computed(()=>countryOptions(locale.value));
const visibleCountries=computed(()=>countries.value.filter(item=>(countryFilter.value!=='selected'||form.country_access_blocked.includes(item.code))&&(!countrySearch.value.trim()||[item.code,item.name,item.alternate].join(' ').toLocaleLowerCase().includes(countrySearch.value.trim().toLocaleLowerCase()))));
const blocksOwnCountry=computed(()=>!props.remoteSite&&form.country_access_enabled&&!!accessPreview.value?.country_code&&form.country_access_blocked.includes(accessPreview.value.country_code));
function selectNavigation(id:string,checked:boolean){if(id==='settings')return;const values=new Set(navigationSelection.value);if(checked)values.add(id);else values.delete(id);values.add('settings');navigationSelection.value=[...values];}
function resetNavigation(){navigationSelection.value=[...(navigationRole.value==='admin'?DEFAULT_ADMIN_SIDEBAR:DEFAULT_MEMBER_SIDEBAR)];}
function selectCountry(code:string,checked:boolean){const values=new Set(form.country_access_blocked);if(checked)values.add(code);else values.delete(code);form.country_access_blocked=[...values].sort();}
function receive(value:SiteSettings){Object.assign(form,value,{sidebar_admin:[...(value.sidebar_admin??DEFAULT_ADMIN_SIDEBAR)],sidebar_member:[...(value.sidebar_member??DEFAULT_MEMBER_SIDEBAR)],country_access_blocked:[...(value.country_access_blocked||[])]});}
async function revealInvalid(event:Event){event.preventDefault();const target=event.target as HTMLInputElement;emit('showSection',target.closest<HTMLElement>('[data-setting-section]')?.dataset.settingSection||'site');error.value=target.validationMessage;await nextTick();target.focus();}
async function loadAccess(){if(props.remoteSite||accessLoading.value)return;accessLoading.value=true;accessError.value='';try{accessPreview.value=await api<AccessPreview>('/access-check');}catch(e){if(!isCancelled(e))accessError.value=(e as Error).message;}finally{accessLoading.value=false;}}
watch(()=>[form.country_access_enabled,form.country_access_blocked.join(','),accessPreview.value?.country_code],()=>{confirmOwnCountry.value=false;});
watch(form,()=>{saved.value=false;},{deep:true,flush:'sync'});
async function load(){const request=loadRequest.start();try{const value=await api<SiteSettings>('/settings','GET',undefined,{signal:request.signal});if(!loadRequest.isCurrent(request))return;receive(value);ready.value=true;error.value='';}catch(e){if(loadRequest.isCurrent(request)&&!isCancelled(e))error.value=(e as Error).message;}}
async function save(){if(busy.value||blocksOwnCountry.value&&!confirmOwnCountry.value)return;busy.value=true;loadRequest.cancel();error.value='';saved.value=false;try{const value=await api<SiteSettings>('/settings','PUT',form);receive(value);saved.value=true;emit('saved');}catch(e){if(!isCancelled(e))error.value=(e as Error).message;}finally{busy.value=false;}}
onMounted(()=>{void load();void loadAccess();});
</script>
<template>
<section class="site-preferences">
 <p v-if="error" class="error" role="alert">{{t(error)}} <button @click="load">{{t('重新加载')}}</button></p>
 <p v-if="saved" class="settings-saved" role="status">{{t('系统设置已保存并生效')}}</p>
 <form v-if="ready" @submit.prevent="save" @invalid.capture="revealInvalid">
  <fieldset class="preference-grid" :disabled="busy">
   <section v-show="section==='site'" data-setting-section="site" class="settings-card"><header><Building2 :size="20"/><div><h2>{{t('站点信息')}}</h2><p>{{t('品牌、默认语言与成员联系方式')}}</p></div></header>
    <div class="settings-fields"><label>{{t('面板名称')}}<input v-model="form.panel_name" required maxlength="40"/></label><label>{{t('组织名称')}}<input v-model="form.organization" required maxlength="60"/></label><label>{{t('默认语言')}}<select v-model="form.default_locale"><option value="zh-CN">简体中文</option><option value="en">English</option></select></label><label>{{t('联系邮箱')}}<input v-model="form.support_email" type="email" maxlength="254" placeholder="support@example.com"/></label></div>
    <label>{{t('登录公告')}}<textarea v-model="form.login_notice" rows="3" maxlength="500" :placeholder="t('可填写维护时间或访问说明')"/></label><small>{{form.login_notice.length}} / 500 · {{t('对未登录访客可见')}}</small>
   </section>
   <section v-show="section==='site'" class="settings-card access-preferences"><header><ShieldCheck :size="20"/><div><h2>{{t('注册与访问')}}</h2><p>{{t('管理成员加入方式和公共功能入口')}}</p></div></header>
    <label class="preference-toggle"><span><strong>{{t('开放注册')}}</strong><small>{{t('注册账号默认获得演示套餐')}}</small></span><input v-model="form.registration_enabled" type="checkbox" role="switch"/></label>
    <label class="preference-toggle" :class="{muted:!form.registration_enabled}"><span><strong>{{t('拼图滑动验证')}}</strong><small>{{t('注册前完成拼图验证，支持手机与桌面')}}</small></span><input v-model="form.registration_captcha" type="checkbox" role="switch" :disabled="!form.registration_enabled"/></label>
    <div class="preference-note">{{t('用户订阅由生效套餐决定，套餐销售请前往“套餐上架”。')}}</div>
    <label class="preference-toggle public-toggle"><span><strong>{{t('公共功能显示')}}</strong><small>{{t('显示公共 IP 池、公共节点和公共订阅')}}</small></span><input :checked="publicFeaturesEnabled" type="checkbox" role="switch" @change="emit('updatePublicFeaturesEnabled',($event.target as HTMLInputElement).checked)"/></label><small>{{t('此显示偏好在当前浏览器立即生效，已有数据不会删除。')}}</small>
   </section>
   <section v-show="section==='navigation'" class="settings-card navigation-preferences"><header><Navigation :size="20"/><div><h2>{{t('侧边栏入口')}}</h2><p>{{t('只把常用功能放在侧边栏，其余入口保留在“更多功能”和功能搜索中。')}}</p></div></header>
    <div class="navigation-role" role="group" :aria-label="t('配置角色')"><button type="button" :aria-pressed="navigationRole==='admin'" @click="navigationRole='admin'">{{t('管理员侧边栏')}}</button><button type="button" :aria-pressed="navigationRole==='member'" @click="navigationRole='member'">{{t('成员侧边栏')}}</button><button type="button" class="navigation-reset" @click="resetNavigation">{{t('恢复精简默认')}}</button></div>
    <div class="navigation-options"><label v-for="item in navigationOptions" :key="item.id" :class="{fixed:item.id==='settings'}"><input type="checkbox" :checked="item.id==='settings'||navigationSelection.includes(item.id)" :disabled="item.id==='settings'" @change="selectNavigation(item.id,($event.target as HTMLInputElement).checked)"/><span>{{navigationRole==='member'?t(item.label):item.label}}<small v-if="item.id==='settings'">{{t('固定入口')}}</small></span></label></div>
    <p class="preference-note">{{t('隐藏入口不会关闭功能，也不会修改用户权限。设置入口始终保留。')}}</p>
   </section>
   <section v-show="section==='access'" class="settings-card delivery-preferences"><header><Download :size="20"/><div><h2>{{t('客户端下载')}}</h2><p>{{t('为访问 GitHub 较慢的用户提供本站下载中继。')}}</p></div></header><label class="preference-toggle"><span><strong>{{t('通过本站中继 GitHub 客户端下载')}}</strong><small>{{t('开启后，支持的 GitHub 安装包由本站服务器转发给用户，会消耗本站带宽。默认关闭。')}}</small></span><input v-model="form.client_download_relay" type="checkbox" role="switch"/></label></section>
   <section v-show="section==='access'" class="settings-card country-preferences"><header><Globe2 :size="20"/><div><h2>{{t('按国家或地区限制访问')}}</h2><p>{{t('按访问 IP 的归属地阻止访问面板，默认关闭。')}}</p></div></header><label class="preference-toggle"><span><strong>{{t('启用国家访问限制')}}</strong><small>{{t('名单内的国家或地区将无法访问面板，管理员也不例外。')}}</small></span><input v-model="form.country_access_enabled" type="checkbox" role="switch"/></label>
    <div v-if="remoteSite" class="access-preview"><div><strong>{{t('正在远程配置子站')}}</strong><p>{{t('访问限制按子站收到的访客 IP 判断。请直接打开子站设置查看当前访问位置，再确认禁止名单。')}}</p></div></div>
    <div v-else class="access-preview"><div><strong>{{t('当前访问位置')}}</strong><p v-if="accessPreview"><code>{{accessPreview.ip||'—'}}</code> · {{accessPreview.country_name||t('未知位置')}} <span v-if="accessPreview.country_code">({{accessPreview.country_code}})</span></p><p v-else>{{accessLoading?t('检测中…'):t('暂时无法识别当前访问位置')}}</p><small v-if="accessPreview?.database_version">{{t('国家数据库')}} · {{accessPreview.database_version}}</small><p v-if="accessError" class="error" role="alert">{{t(accessError)}}</p><a href="https://db-ip.com" target="_blank" rel="noopener noreferrer">IP Geolocation by DB-IP</a></div><button type="button" :disabled="accessLoading||busy" @click="loadAccess"><RefreshCw :size="15" :class="{spin:accessLoading}"/>{{t('重新检测')}}</button></div>
    <fieldset class="country-fields" :disabled="!form.country_access_enabled"><div class="country-toolbar"><label class="country-search"><Search :size="16"/><input v-model="countrySearch" type="search" :placeholder="t('搜索国家、地区或代码')" :aria-label="t('搜索国家、地区或代码')"/></label><select v-model="countryFilter" :aria-label="t('国家列表筛选')"><option value="all">{{t('全部国家与地区')}}</option><option value="selected">{{t('仅看已禁止')}}</option></select></div><p class="country-count">{{t('已禁止')}} {{form.country_access_blocked.length}} {{t('个国家或地区')}}<button v-if="form.country_access_blocked.length" type="button" @click="form.country_access_blocked=[]">{{t('清空名单')}}</button></p><div class="country-options" tabindex="0" :aria-label="t('禁止访问的国家与地区')"><label v-for="country in visibleCountries" :key="country.code" :class="{selected:form.country_access_blocked.includes(country.code)}"><input type="checkbox" :checked="form.country_access_blocked.includes(country.code)" @change="selectCountry(country.code,($event.target as HTMLInputElement).checked)"/><span>{{country.name}}<small>{{country.code}}<template v-if="country.code===accessPreview?.country_code"> · {{t('当前位置')}}</template></small></span></label><p v-if="!visibleCountries.length" class="field-help">{{t('没有匹配的国家或地区')}}</p></div><label>{{t('禁止访问提示')}}<textarea v-model="form.country_access_reason" rows="3" maxlength="500" :placeholder="t('该地区暂不提供访问，请联系管理员。')"/></label><small>{{t('被限制的访客会看到这段说明。')}}</small></fieldset>
    <div v-if="blocksOwnCountry" class="own-country-warning" role="alert"><TriangleAlert :size="20"/><div><strong>{{t('当前访问位置也在禁止名单中')}}</strong><p>{{t('保存后，你当前的浏览器也将无法访问面板。需从允许的地区访问，或通过服务器关闭限制。')}}</p><label><input v-model="confirmOwnCountry" type="checkbox"/>{{t('我已确认其他管理方式，仍要禁止当前地区')}}</label></div></div>
   </section>
  </fieldset>
  <footer class="settings-save"><span v-if="blocksOwnCountry&&!confirmOwnCountry">{{t('保存前请确认当前地区的访问限制。')}} <button v-if="section!=='access'" type="button" @click="emit('showSection','access')">{{t('前往确认')}}</button></span><span v-else>{{t('修改面板设置不会中断节点连接')}}</span><button class="primary" :disabled="busy||(blocksOwnCountry&&!confirmOwnCountry)"><Save :size="16"/>{{t(busy?'保存中…':'保存站点设置')}}</button></footer>
 </form><p v-else-if="!error" role="status">{{t('加载中…')}}</p>
</section>
</template>
<style scoped>
.preference-grid{border:0;padding:0;margin:0;min-width:0;display:grid;grid-template-columns:1.2fr 1fr;gap:18px;align-items:start}.settings-fields{gap:16px}.settings-card header{margin-bottom:20px}.settings-card .preference-toggle{display:flex;flex-direction:row;align-items:center;justify-content:space-between;gap:20px;margin:0;padding:18px 0;border-bottom:1px solid var(--border);cursor:pointer;white-space:normal}.preference-toggle>span{min-width:0}.preference-toggle strong{display:block;font-size:13px;font-weight:550}.preference-toggle small{display:block;margin-top:6px}.settings-card .preference-toggle input{appearance:none;width:37px;height:22px;min-height:22px;flex:0 0 37px;border:1px solid var(--border);border-radius:20px;background:var(--input);position:relative;cursor:pointer;margin:0;padding:0;transition:background .15s}.preference-toggle input:before{content:'';position:absolute;width:14px;height:14px;top:3px;left:3px;border-radius:50%;background:var(--muted);transition:transform .15s}.preference-toggle input:checked{background:var(--accent-soft);border-color:var(--accent)}.preference-toggle input:checked:before{transform:translateX(15px);background:var(--accent)}.preference-toggle input:focus-visible{outline:2px solid var(--accent);outline-offset:3px}.muted{opacity:.55}.preference-note{padding:14px;border-radius:8px;background:var(--accent-soft);font-size:12px;line-height:1.7;color:var(--secondary);margin:18px 0 2px}.settings-card .public-toggle{border-bottom:0;padding-bottom:8px}.settings-save{position:sticky;bottom:0;padding:16px 0;background:var(--surface);border-top:1px solid var(--border);z-index:1;margin-top:18px;border-radius:8px}.settings-save>span{padding-left:12px}.settings-save>button{margin-right:12px}@media(max-width:850px){.preference-grid{grid-template-columns:1fr}.settings-fields{grid-template-columns:1fr 1fr}}@media(max-width:900px){.settings-save{bottom:calc(76px + env(safe-area-inset-bottom, 0px))}}@media(max-width:500px){.settings-fields{grid-template-columns:1fr}.settings-save{align-items:center}.settings-save>span{font-size:12px}.settings-save>button{font-size:12px;padding:9px 12px}}
.navigation-role{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:16px}.navigation-role button{min-height:44px;font-size:13px}.navigation-role button[aria-pressed=true]{background:var(--accent-soft);border-color:var(--accent);color:var(--accent-text)}.navigation-reset{margin-left:auto}.navigation-options{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.navigation-options label,.country-options label{display:flex;flex-direction:row;align-items:center;gap:10px;min-height:48px;margin:0;padding:11px 12px;border:1px solid var(--border);border-radius:9px;font-size:13px;cursor:pointer}.navigation-options label>span,.country-options label>span{min-width:0;flex:1;overflow-wrap:anywhere}.navigation-options input,.country-options input,.own-country-warning input{width:18px;height:18px;min-height:0;flex-shrink:0;accent-color:var(--accent);margin:0}.navigation-options small{display:inline;margin-left:8px}.navigation-options .fixed{background:var(--surface-raised);cursor:default}.access-preview{display:flex;align-items:flex-start;gap:14px;justify-content:space-between;padding:16px;background:var(--surface-raised);border-radius:10px;margin:18px 0}.access-preview strong{font-size:13px}.access-preview p{font-size:13px;line-height:1.7;margin:6px 0;overflow-wrap:anywhere}.access-preview code{font-family:inherit}.access-preview a{display:block;margin-top:8px;font-size:12px;color:var(--accent-text)}.access-preview button{flex-shrink:0;min-height:44px;font-size:12px}.country-fields{border:0;min-width:0;padding:0;margin:0}.country-fields:disabled{opacity:.6}.country-toolbar{display:flex;gap:10px;align-items:center}.country-search{display:flex!important;flex-direction:row!important;align-items:center;gap:8px;margin:0!important;flex:1;min-width:0}.country-search input{min-width:0;flex:1}.country-toolbar select{width:auto;max-width:180px;font-size:13px}.country-count{display:flex;align-items:center;gap:5px;margin:12px 0;font-size:13px;color:var(--secondary)}.country-count button{margin-left:auto;font-size:12px;min-height:44px}.country-options{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;max-height:320px;overflow:auto;overscroll-behavior:contain;padding:3px;margin-bottom:20px;scroll-padding:8px}.country-options label.selected{background:var(--accent-soft);border-color:var(--accent)}.country-options small{display:block;margin-top:4px;color:var(--muted);font-size:12px}.own-country-warning{display:flex;align-items:flex-start;gap:10px;padding:16px;border:1px solid var(--warning);background:var(--warning-soft);border-radius:10px;margin-top:18px;color:var(--warning)}.own-country-warning>svg{flex-shrink:0}.own-country-warning strong{font-size:14px}.own-country-warning p{font-size:13px;line-height:1.7;margin:7px 0}.own-country-warning label{display:flex;flex-direction:row;gap:10px;align-items:center;font-size:13px;line-height:1.7;min-height:44px;margin:8px 0 0}.country-preferences,.navigation-preferences,.delivery-preferences{grid-column:1/-1}.country-fields textarea{width:100%}@media(max-width:600px){.navigation-options,.country-options{grid-template-columns:1fr}.navigation-reset{margin-left:0}.country-toolbar{flex-wrap:wrap}.country-search{flex-basis:100%}.country-toolbar select{width:100%;max-width:none}.access-preview{flex-direction:column}.access-preview button{align-self:flex-start}.country-options{max-height:300px}}
</style>
